def count_target_blocks(grid, target):
    R, C = len(grid), len(grid[0])
    total = 0
    for top in range(R):
        col = [0] * C
        for bottom in range(top, R):
            row = grid[bottom]
            for c in range(C):
                col[c] += row[c]
            seen = {0: 1}
            run = 0
            for v in col:
                run += v
                total += seen.get(run - target, 0)
                seen[run] = seen.get(run, 0) + 1
    return total

